from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import CustomPersonalToken

class UpdatePersonalTokenMetadataView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def patch(self, request, token_id):
        try:
            token = CustomPersonalToken.objects.get(id=token_id, user=request.user)
        except CustomPersonalToken.DoesNotExist:
            return Response({'error': 'Token not found or unauthorized'}, status=status.HTTP_404_NOT_FOUND)

        new_label = request.data.get('label')
        if new_label:
            token.label = new_label
            token.save(update_fields=['label'])
        return Response({'id': token.id, 'label': token.label})
